CREATE TABLE sub13_employees (employee_id INTEGER PRIMARY KEY, employee_name TEXT NOT NULL, department_id INTEGER NOT NULL, salary INTEGER NOT NULL);
INSERT INTO sub13_employees VALUES (1, 'Asha', 1, 100), (2, 'Ravi', 1, 80), (3, 'Mira', 2, 90), (4, 'Noor', 2, 70);
SELECT e.employee_name FROM sub13_employees AS e WHERE e.salary > (SELECT AVG(x.salary) FROM sub13_employees AS x WHERE x.department_id = e.department_id) ORDER BY e.employee_name;

